  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00089",
          "explanation": "The doctor integrated the discovered acromegaly/endocrine follow-up context into a targeted plan.",
          "quote": "评估垂体生长激素瘤术后恢复情况"
        },
        {
          "event_id": "lite_evt_00118",
          "explanation": "The doctor used the newly clarified injection timing to prioritize next-week octreotide execution.",
          "quote": "上一针是三周前打的"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor elicited and used multiple non-volunteered action-relevant facts, including specific IGF values, nasal-entry status, and the last/next octreotide timing, and converted them into a tailored endocrine/injection plan.",
